ProcessResult::ProcessResult() : tag_(Tag::UNMAPPED_FIELD) {
  data_.unmapped_field = bool();
}

ProcessResult::~ProcessResult() {
  DestroyActive();
}


void ProcessResult::set_unmapped_field(
    bool unmapped_field) {
  if (tag_ != Tag::UNMAPPED_FIELD) {
    DestroyActive();
    tag_ = Tag::UNMAPPED_FIELD;
  }
  data_.unmapped_field = unmapped_field;
}
void ProcessResult::set_process_info(
    ProcessInfoPtr process_info) {
  if (tag_ == Tag::PROCESS_INFO) {
    *(data_.process_info) = std::move(process_info);
  } else {
    DestroyActive();
    tag_ = Tag::PROCESS_INFO;
    data_.process_info = new ProcessInfoPtr(
        std::move(process_info));
  }
}
void ProcessResult::set_error(
    ProbeErrorPtr error) {
  if (tag_ == Tag::ERROR) {
    *(data_.error) = std::move(error);
  } else {
    DestroyActive();
    tag_ = Tag::ERROR;
    data_.error = new ProbeErrorPtr(
        std::move(error));
  }
}

void ProcessResult::DestroyActive() {
  switch (tag_) {

    case Tag::UNMAPPED_FIELD:

      break;
    case Tag::PROCESS_INFO:

      delete data_.process_info;
      break;
    case Tag::ERROR:

      delete data_.error;
      break;
  }
}
size_t ProcessResult::Hash(size_t seed) const {
  seed = mojo::internal::HashCombine(seed, static_cast<uint32_t>(tag_));
  switch (tag_) {

    case Tag::UNMAPPED_FIELD:
      return mojo::internal::Hash(seed, data_.unmapped_field);
    case Tag::PROCESS_INFO:
      return mojo::internal::Hash(seed, data_.process_info);
    case Tag::ERROR:
      return mojo::internal::Hash(seed, data_.error);
    default:
      NOTREACHED();
      return seed;
  }
}

bool ProcessResult::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
